def transform(g):
    H,W=len(g),len(g[0])
    objs=objects(g)
    anchor=max(objs,key=lambda o:max(c for r,c in o[1]))  # highest color value anchors the rows
    at=min(r for r,c in anchor[1])
    out=[[0]*W for _ in range(H)]
    for col,cells in objs:
        t=min(r for r,c in cells)
        for r,c in cells: out[r-t+at][c]=col
    return out
